import re

def score(rolls: str) -> int:
    # Validate empty input
    if not rolls:
        raise ValueError("Empty input")

    # Split into frames
    frames = rolls.split()

    # Must have exactly 10 frames
    if len(frames) != 10:
        raise ValueError("not exactly ten space-separated frames")

    # Validate each frame
    for i, frame in enumerate(frames):
        # Check for invalid characters
        if not re.match(r'^[0-9X/]-$', frame):
            raise ValueError("invalid characters")

        # Check for lone "/"
        if frame == "/":
            raise ValueError("lone '/'")

        # Determine number of rolls in this frame
        if frame == "X":
            num_rolls = 1
        elif frame == "-":
            num_rolls = 2
        elif frame == "/":
            num_rolls = 2
        else:
            # Two-digit frame (open frame)
            num_rolls = 2

        # Validate frame length
        if len(frame) != num_rolls:
            raise ValueError("wrong frame lengths")

        # Check for open frame with > 10 pins
        if frame != "X" and frame != "-":
            pin_sum = int(frame[0]) + int(frame[1])
            if pin_sum > 10:
                raise ValueError("an open frame knocking over more than 10 pins")

    # Calculate total score
    total = 0
    roll_index = 0

    for frame_num in range(10):
        frame_str = frames[frame_num]

        if frame_str == "X":
            # Strike: score is 10 + next 2 rolls
            frame_score = 10
            bonus_rolls = 2
        elif frame_str == "-":
            # Miss: score is 0
            frame_score = 0
            bonus_rolls = 0
        elif frame_str == "/":
            # Spare: score is 10 + next roll
            frame_score = 10
            bonus_rolls = 1
        else:
            # Open frame: score is sum of 2 rolls
            frame_score = int(frame_str[0]) + int(frame_str[1])
            bonus_rolls = 0

        total += frame_score

        # Add bonus rolls to total
        for _ in range(bonus_rolls):
            if roll_index >= len(frames):
                break
            bonus_roll = frames[roll_index]
            if bonus_roll == "X":
                bonus = 10
            elif bonus_roll == "-":
                bonus = 0
            elif bonus_roll == "/":
                bonus = 10 + next_roll_score(roll_index + 1)
            else:
                bonus = int(bonus_roll)
            total += bonus
            roll_index += 1

        # Move past this frame's rolls
        if frame_str == "X":
            roll_index += 1
        else:
            roll_index += 2

    return total

def next_roll_score(index: int) -> int:
    """Get the score of the next roll (for bonus calculation)."""
    if index >= len(frames):
        return 0
    frame_str = frames[index]
    if frame_str == "X":
        return 10
    elif frame_str == "-":
        return 0
    elif frame_str == "/":
        return 10 + next_roll_score(index + 1)
    else:
        return int(frame_str)

# Global frames for next_roll_score
global frames

def _get_frames():
    global frames
    if frames is None:
        frames = rolls.split()
    return frames

def next_roll_score(index: int) -> int:
    global frames
    frames = _get_frames()
    if index >= len(frames):
        return 0
    frame_str = frames[index]
    if frame_str == "X":
        return 10
    elif frame_str == "-":
        return 0
    elif frame_str == "/":
        return 10 + next_roll_score(index + 1)
    else:
        return int(frame_str)
