"""
Integer arithmetic evaluator.
Supports integer literals, +, -, *, /, parentheses.
Unary minus supported. Truncating division toward zero.
"""

from typing import List, Tuple, Union

Token = Union[str, int]
TokenType = str

class Tokenizer:
    def __init__(self, expr: str):
        self.expr = expr
        self.pos = 0
        self.tokens: List[Token] = []

    def tokenize(self) -> List[Token]:
        while self.pos < len(self.expr):
            self._skip_whitespace()
            if self.pos >= len(self.expr):
                break

            ch = self.expr[self.pos]

            if ch.isdigit():
                self._read_number()
            elif ch in '+-*/':
                self.tokens.append(ch)
                self.pos += 1
            elif ch == '(':
                self.tokens.append('(')
                self.pos += 1
            elif ch == ')':
                self.tokens.append(')')
                self.pos += 1
            else:
                raise ValueError(f"Invalid character: {ch}")

        self.tokens.append('EOF')
        return self.tokens

    def _skip_whitespace(self):
        while self.pos < len(self.expr) and self.expr[self.pos] in ' \t\n\r':
            self.pos += 1

    def _read_number(self):
        start = self.pos
        while self.pos < len(self.expr) and self.expr[self.pos].isdigit():
            self.pos += 1
        num_str = self.expr[start:self.pos]
        if not num_str:
            raise ValueError("Empty number")
        self.tokens.append(int(num_str))

    def peek(self) -> Token:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return 'EOF'

    def consume(self) -> Token:
        token = self.peek()
        self.pos += 1
        return token


class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def parse(self) -> int:
        result = self._expr()
        if self.pos < len(self.tokens) and self.tokens[self.pos] != 'EOF':
            raise ValueError("Unexpected token after expression")
        return result

    def _expr(self) -> int:
        result = self._term()
        while self.peek() in ('+', '-'):
            op = self.consume()
            right = self._term()
            if op == '+':
                result += right
            else:
                result -= right
        return result

    def _term(self) -> int:
        result = self._factor()
        while self.peek() in ('*', '/'):
            op = self.consume()
            right = self._factor()
            if op == '*':
                result *= right
            else:
                result //= right  # Truncating division toward zero
        return result

    def _factor(self) -> int:
        token = self.peek()

        if token == '(':
            self.consume()
            result = self._expr()
            if self.consume() != ')':
                raise ValueError("Missing closing parenthesis")
            return result

        elif token == '-':
            self.consume()
            return -self._factor()

        elif token == 'EOF':
            raise ValueError("Unexpected end of input")

        else:
            num = self.consume()
            if not isinstance(num, int):
                raise ValueError("Expected number")
            return num


def evaluate(expr: str) -> int:
    tokenizer = Tokenizer(expr)
    parser = Parser(tokenizer.tokenize())
    return parser.parse()
